// Embedded 192px RGBA pilot from the generated alien PNG. Library v1 has no asset envelope.
const pixels = '';
export function pilotPixels() {
  const data = new Uint8Array(pixels.length / 2);
  for (let i = 0; i < data.length; i++) data[i] = parseInt(pixels.slice(i * 2, i * 2 + 2), 16);
  return data;
}
